-- Arrowgo Logistics: schema + seed data (MySQL / MariaDB via XAMPP)
CREATE DATABASE IF NOT EXISTS arrowgo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE arrowgo;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS inquiries,news,location_categories,locations,service_categories,service_facts,service_inclusions,services,categories;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60) NOT NULL UNIQUE,sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE services(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,title VARCHAR(160) NOT NULL,description TEXT NOT NULL,icon_paths TEXT NOT NULL,sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE service_inclusions(id INT AUTO_INCREMENT PRIMARY KEY,service_id INT NOT NULL,text VARCHAR(200) NOT NULL,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE);
CREATE TABLE service_facts(id INT AUTO_INCREMENT PRIMARY KEY,service_id INT NOT NULL,value VARCHAR(80) NOT NULL,label VARCHAR(80) NOT NULL,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE);
CREATE TABLE service_categories(service_id INT NOT NULL,category_id INT NOT NULL,PRIMARY KEY(service_id,category_id),FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE);
CREATE TABLE locations(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,region_group ENUM('Luzon','Visayas','Mindanao') NOT NULL,region VARCHAR(120) NOT NULL,type VARCHAR(80) NOT NULL,address VARCHAR(255) NOT NULL,map_x DECIMAL(6,1) NOT NULL,map_y DECIMAL(6,1) NOT NULL,lat DECIMAL(8,4) NOT NULL,lng DECIMAL(8,4) NOT NULL);
CREATE TABLE location_categories(location_id INT NOT NULL,category_id INT NOT NULL,PRIMARY KEY(location_id,category_id),FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE);
CREATE TABLE news(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,image_path VARCHAR(255) NOT NULL,image_alt VARCHAR(255) NOT NULL,published_at DATE NOT NULL);
CREATE TABLE inquiries(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL,company VARCHAR(160) NULL,service VARCHAR(60) NULL,message TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
